package com.orderflow.notification.service;
import com.orderflow.notification.config.NotificationReconciliationProperties;import com.orderflow.notification.domain.NotificationDeliveryStatus;import com.orderflow.notification.repository.NotificationDeliveryRepository;import com.orderflow.scheduler.JobResult;import com.orderflow.scheduler.PostgresJobScheduler;import io.micrometer.core.instrument.MeterRegistry;import java.time.Clock;import java.time.Instant;import java.util.concurrent.atomic.AtomicLong;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component public class NotificationReconciliationJob{private final NotificationReconciliationProperties properties;private final NotificationDeliveryRepository deliveries;private final NotificationReconciliationService reconciliation;private final PostgresJobScheduler scheduler;private final MeterRegistry metrics;private final Clock clock;private final AtomicLong stuck=new AtomicLong();public NotificationReconciliationJob(NotificationReconciliationProperties p,NotificationDeliveryRepository d,NotificationReconciliationService r,PostgresJobScheduler s,MeterRegistry m,Clock c){properties=p;deliveries=d;reconciliation=r;scheduler=s;metrics=m;clock=c;metrics.gauge("notification_deliveries_stuck",stuck);}@Scheduled(fixedDelayString="${app.notification.reconciliation.delay:30s}",initialDelayString="${app.notification.reconciliation.delay:30s}")public void reconcile(){if(!properties.enabled())return;scheduler.execute("notificationDeliveryReconciliationJob",properties.lockDuration(),correlation->{metrics.counter("notification_reconciliation_runs_total").increment();Instant cutoff=Instant.now(clock).minus(properties.staleThreshold());stuck.set(deliveries.countByStatusAndUpdatedAtBefore(NotificationDeliveryStatus.PROCESSING,cutoff));long processed=0,failures=0;for(var id:deliveries.findStaleProcessingIds(cutoff,properties.batchSize())){try{var outcome=reconciliation.recover(id,correlation);if(outcome==NotificationReconciliationService.Outcome.RECOVERED){processed++;metrics.counter("notification_reconciliation_recovered_total").increment();}else if(outcome==NotificationReconciliationService.Outcome.FAILED){processed++;failures++;metrics.counter("notification_reconciliation_failed_total").increment();}}catch(RuntimeException exception){failures++;metrics.counter("notification_reconciliation_failed_total").increment();}}stuck.set(deliveries.countByStatusAndUpdatedAtBefore(NotificationDeliveryStatus.PROCESSING,cutoff));return new JobResult(processed,failures);});}}
